import { elementsToPos, orbitPath, solveKepler, meanMotion } from '/tmp/orb.mjs';
import { jdFromDate, dateFromJd, parseDateInput } from '/tmp/orb.mjs';
let fails = 0;
const ok = (name, cond, extra='') => { if (!cond) { fails++; console.log('FAIL', name, extra); } else console.log('ok', name, extra); };
const out = [0,0,0];
// Earth at J2000 epoch: M=357.5° -> near perihelion, r ~= a(1-e) = 0.9833
const earth = {a:1.00000261,e:0.01671123,i:-0.00001531,om:0,w:102.937682,ma:357.52689,epoch:2451545,n:0.985604,tp:NaN,q:NaN};
elementsToPos(earth, 2451545, out);
const r = Math.hypot(out[0],out[1],out[2]);
ok('earth r at epoch ~0.9833', Math.abs(r-0.9833)<0.002, r.toFixed(5));
// closure after one period
const per = 365.2569;
elementsToPos(earth, 2451545+per, out);
const r2 = Math.hypot(out[0],out[1],out[2]);
elementsToPos(earth, 2451545, out);
const dx = Math.hypot(out[0]-0,0,0); // placeholder
import('node:assert');
const p1 = [0,0,0], p2=[0,0,0];
elementsToPos(earth, 2451545, p1); elementsToPos(earth, 2451545+per, p2);
ok('earth closes after 1 period', Math.hypot(p1[0]-p2[0],p1[1]-p2[1],p1[2]-p2[2])<1e-6);
// Eros at epoch within [q, ad]
const eros = {a:1.458,e:0.2229,i:10.83,om:304.27,w:178.92,ma:62.51,epoch:2461200.5,n:0.5597,tp:2461088.81,q:1.133};
elementsToPos(eros, 2461200.5, out);
const re = Math.hypot(out[0],out[1],out[2]);
ok('eros r in [1.133,1.783]', re>=1.132 && re<=1.784, re.toFixed(4));
// Halley at tp -> r == q
const halley = {a:17.93,e:0.9679,i:162.19,om:59.1,w:112.24,ma:274.38,epoch:2439875.5,n:0.01298,tp:2446469.97,q:0.575};
elementsToPos(halley, 2446469.97, out);
const rh = Math.hypot(out[0],out[1],out[2]);
ok('halley r(tp)==q', Math.abs(rh-0.575)<1e-3, rh.toFixed(5));
// hyperbolic: e=1.2, q=0.5 -> r(tp)==q
const hyp = {a:NaN,e:1.2,i:10,om:20,w:30,ma:NaN,epoch:2460000,n:NaN,tp:2460000.5,q:0.5};
elementsToPos(hyp, 2460000.5, out);
const rhu = Math.hypot(out[0],out[1],out[2]);
ok('hyperbolic r(tp)==q', Math.abs(rhu-0.5)<1e-6, rhu.toFixed(6));
elementsToPos(hyp, 2460000.5+100, out);
ok('hyperbolic +100d finite & farther', Number.isFinite(out[0]) && Math.hypot(out[0],out[1],out[2])>0.5);
// parabolic e=1
const par = {a:NaN,e:1.0,i:5,om:10,w:20,ma:NaN,epoch:2460000,n:NaN,tp:2460000,q:1.0};
elementsToPos(par, 2460000, out);
ok('parabolic r(tp)==q', Math.abs(Math.hypot(out[0],out[1],out[2])-1.0)<1e-6);
// time utils
ok('jdFromDate J2000', Math.abs(jdFromDate(2000,1,1,12,0,0)-2451545.0)<1e-9);
ok('roundtrip', Math.abs(parseDateInput('2026-09-04') - jdFromDate(2026,9,4))<1e-9);
const d = dateFromJd(2451545.0);
ok('dateFromJd', d.getUTCFullYear()===2000 && d.getUTCMonth()===0 && d.getUTCDate()===1 && d.getUTCHours()===12);
// orbit path closes for ellipse
const pts = orbitPath(eros, 64);
const dd = Math.hypot(pts[0]-pts[192], pts[1]-pts[193], pts[2]-pts[194]);
ok('orbitPath closes', dd < 1e-4, dd.toExponential(1));
console.log(fails === 0 ? 'ALL PASS' : fails + ' FAILURES');
process.exit(fails ? 1 : 0);
EOF
